-- 150: Original BrillaPrep WASSCE BrillaPrep transitional Auto Mechanics beta content blueprint questions, part 8.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_150_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_150_guard;
INSERT INTO _migration_150_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_036' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_8' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In the tyre marking 205/55 R16, what does 205 represent?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The tyre aspect ratio as a percentage","B. The wheel diameter in inches","C. The tyre load index","D. The nominal section width in millimetres"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The first number is nominal tyre section width in millimetres; 55 is aspect ratio and 16 is the wheel diameter in inches. Therefore the correct answer is D: The nominal section width in millimetres.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_036' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_150_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_037' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_8' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What tool should be used to check tyre inflation pressure?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A calibrated tyre-pressure gauge","B. A tread-depth gauge","C. A wheel-nut torque wrench","D. A dial indicator on the wheel rim"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A pressure gauge measures the air pressure directly so it can be compared with the vehicle manufacturer’s cold-pressure recommendation. Therefore the correct answer is A: A calibrated tyre-pressure gauge.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_037' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_150_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_038' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_8' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What tread pattern is most associated with persistent over-inflation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Greater wear on both outer shoulders","B. Greater wear along the centre of the tread","C. Feathered wear caused by incorrect toe","D. Cupped wear caused by poor damping"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Excess pressure tends to crown the tread so the centre carries a disproportionate load, although alignment and duty must also be checked. Therefore the correct answer is B: Greater wear along the centre of the tread.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_038' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_150_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_039' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_8' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should diagnostic trouble codes not be treated as automatic proof that the named component is faulty?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The code proves the named sensor itself has failed","B. Clearing the code confirms the fault is repaired","C. A code identifies a detected circuit or system condition that still requires testing","D. The named component should be replaced before circuit tests"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Wiring, connectors, mechanical faults or another sensor can cause the monitored condition, so tests and service information must confirm the cause. Therefore the correct answer is C: A code identifies a detected circuit or system condition that still requires testing.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_039' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_150_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_040' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_8' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which maintenance action most directly helps prevent engine damage from a worn timing belt?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Inspect it only after a rattling noise develops","B. Retension the old belt instead of replacing it","C. Wait for visible cracking regardless of service interval","D. Replace the belt and related parts at the specified interval"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Age and mileage weaken timing belts; scheduled replacement reduces the risk of sudden failure and piston-to-valve contact on interference engines. Therefore the correct answer is D: Replace the belt and related parts at the specified interval.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_040' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
